struct Excerpt<'a> {
    part: &'a str,
}

impl<'a> Excerpt<'a> {
    fn first_word(&self) -> &str {
        match self.part.find(' ') {
            Some(i) => &self.part[..i],
            None => self.part,
        }
    }
}

fn main() {
    let novel = String::from("Call me Ishmael. Some years ago...");
    let end = novel.find('.').unwrap_or(novel.len());
    let e = Excerpt { part: &novel[..end] };
    println!("excerpt: {}", e.part);
    println!("first word: {}", e.first_word());
}

