exercise.solution:
fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() >= y.len() {
        x
    } else {
        y
    }
}

fn shorter<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() <= y.len() {
        x
    } else {
        y
    }
}

fn main() {
    println!("{}", longest("tree", "forest"));
    println!("{}", shorter("tree", "forest"));
}
